package com.inventoryquickcheck;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.function.Supplier;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Draws on each bank item that answers an entry of the box how many to take out, in bold orange with a black edge at its
 * bottom-right corner. The bank's own amount at the top-left is left alone.
 */
public final class BankNumbersOverlay extends WidgetItemOverlay
{
	private static final Color ORANGE = new Color(255, 152, 31);

	private final Supplier<ShownResult> shown;
	private final InventoryQuickCheckConfig config;

	public BankNumbersOverlay(Supplier<ShownResult> shown, InventoryQuickCheckConfig config)
	{
		this.shown = shown;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.numberBankItems())
		{
			return;
		}
		final ShownResult result = shown.get();
		if (result == null)
		{
			return;
		}
		final Integer number = result.withdraw().get(itemId);
		if (number == null)
		{
			return;
		}
		final Rectangle bounds = widgetItem.getCanvasBounds();
		final Font font = FontManager.getRunescapeBoldFont();
		graphics.setFont(font);
		final FontMetrics metrics = graphics.getFontMetrics(font);
		final String text = String.valueOf(number);
		final int x = bounds.x + bounds.width - 1 - metrics.stringWidth(text);
		final int y = bounds.y + bounds.height - 1;
		graphics.setColor(Color.BLACK);
		for (int dy = -1; dy <= 1; dy++)
		{
			for (int dx = -1; dx <= 1; dx++)
			{
				if (dx != 0 || dy != 0)
				{
					graphics.drawString(text, x + dx, y + dy);
				}
			}
		}
		graphics.setColor(ORANGE);
		graphics.drawString(text, x, y);
	}
}

package com.inventoryquickcheck;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/** Reads which items the bank holds. Client thread only. */
public final class BankReader
{
	private BankReader()
	{
	}

	/** The ids of the bank's items with quantity above 0 (placeholders left out), in bank order; empty when not loaded. */
	public static int[] read(Client client)
	{
		final ItemContainer container = client.getItemContainer(InventoryID.BANK);
		if (container == null)
		{
			return new int[0];
		}
		final Item[] items = container.getItems();
		final int[] ids = new int[items.length];
		int count = 0;
		for (final Item item : items)
		{
			if (item != null && item.getId() != -1 && item.getQuantity() > 0)
			{
				ids[count++] = item.getId();
			}
		}
		return java.util.Arrays.copyOf(ids, count);
	}
}

package com.inventoryquickcheck;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Whether the bank is open. Client thread only. */
public final class BankState
{
	private BankState()
	{
	}

	public static boolean isOpen(Client client)
	{
		final Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}
}

package com.inventoryquickcheck;

/** The blink schedule of the marks. */
public final class Blink
{
	/** One cycle: lit for {@link #LIT_MS}, then dark until the cycle ends; each dark-then-lit is one flash. */
	private static final long CYCLE_MS = 500;
	private static final long LIT_MS = 300;

	private Blink()
	{
	}

	/**
	 * Whether the marks are lit this long after the check. Lit 0-299, dark 300-499, and so on; after {@code count}
	 * cycles lit for good (1 flash: lit from 500). Steady is always lit; Nonstop never settles.
	 */
	public static boolean lit(long elapsedMs, PotionFlashes flashes)
	{
		final int count = flashes.count();
		if (elapsedMs < 0 || (count >= 0 && elapsedMs >= count * CYCLE_MS))
		{
			return true;
		}
		return elapsedMs % CYCLE_MS < LIT_MS;
	}
}

package com.inventoryquickcheck;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where the Missing box hangs from: left of a rectangle with the tops level, or with its top left at a point (right
 * of the bank). Immutable.
 */
final class BoxAnchor
{
	private final Rectangle beside;
	private final Point topLeft;

	private BoxAnchor(Rectangle beside, Point topLeft)
	{
		this.beside = beside;
		this.topLeft = topLeft;
	}

	/** Hang left of the rectangle, tops level ({@link BoxPlace#of}). */
	static BoxAnchor beside(Rectangle anchor)
	{
		return new BoxAnchor(anchor == null ? null : new Rectangle(anchor), null);
	}

	/** Hang right of the bank: top left 4 px right of its frame, a quarter of the way down it. */
	static BoxAnchor rightOf(Rectangle bank)
	{
		return new BoxAnchor(null, new Point(bank.x + bank.width + 4, bank.y + bank.height / 4));
	}

	/** The box's top left for its size on a canvas. */
	Point place(Dimension box, Dimension canvas)
	{
		if (topLeft != null)
		{
			return new Point(topLeft);
		}
		return BoxPlace.of(beside, box, canvas);
	}
}

package com.inventoryquickcheck;

import java.awt.Point;

/**
 * How many entries the box draws, and in how many columns and rows, for a layout. When the entries do not fit, one
 * place is given to {@code +<n>}, so one fewer entry is drawn than the limit. Pure.
 */
public final class BoxGrid
{
	private final int shown;
	private final int more;
	private final int columns;
	private final int rows;

	private BoxGrid(int shown, int more, int columns, int rows)
	{
		this.shown = shown;
		this.more = more;
		this.columns = columns;
		this.rows = rows;
	}

	public static BoxGrid of(int entries, BoxLayout layout)
	{
		if (entries <= 0)
		{
			return new BoxGrid(0, 0, 0, 0);
		}
		final int perColumn = layout.rowsPerColumn();
		final boolean limited = layout.maxColumns() > 0;
		final int limit = limited ? perColumn * layout.maxColumns() : Integer.MAX_VALUE;
		final int shown = entries > limit ? limit - 1 : entries;
		final int more = entries - shown;
		final int places = shown + (more > 0 ? 1 : 0);
		return new BoxGrid(shown, more, (places + perColumn - 1) / perColumn, Math.min(places, perColumn));
	}

	/** The entries drawn. */
	public int shown()
	{
		return shown;
	}

	/** The number after the plus sign; 0 when nothing is left out. */
	public int more()
	{
		return more;
	}

	public int columns()
	{
		return columns;
	}

	/** Rows of the tallest column. */
	public int rows()
	{
		return rows;
	}

	/** The column (x) and row (y) of a place; columns fill top to bottom. */
	public static Point place(int index, int rowsPerColumn)
	{
		return new Point(index / rowsPerColumn, index % rowsPerColumn);
	}
}

package com.inventoryquickcheck;

/** How the box wraps a long list: rows per column and how many columns at most (0 = no limit). */
public enum BoxLayout
{
	ONE_COLUMN("One column", 8, 1),
	COLUMNS_OF_7("Columns of 7", 7, 0),
	TWO_COLUMNS_OF_7("Two columns of 7", 7, 2),
	TWO_COLUMNS_OF_10("Two columns of 10", 10, 2);

	private final String label;
	private final int rowsPerColumn;
	private final int maxColumns;

	BoxLayout(String label, int rowsPerColumn, int maxColumns)
	{
		this.label = label;
		this.rowsPerColumn = rowsPerColumn;
		this.maxColumns = maxColumns;
	}

	public int rowsPerColumn()
	{
		return rowsPerColumn;
	}

	/** The most columns the layout allows; 0 means no limit. */
	public int maxColumns()
	{
		return maxColumns;
	}

	/** The label RuneLite shows in the settings. */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.inventoryquickcheck;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where the result box goes by default: directly left of the check button's icon, tops level; with no icon to hang
 * from, 10 px in from the canvas's bottom-right corner. Never off the canvas's top or left.
 */
final class BoxPlace
{
	private static final int GAP = 2;
	private static final int MARGIN = 10;

	private BoxPlace()
	{
	}

	static Point of(Rectangle anchor, Dimension box, Dimension canvas)
	{
		if (anchor != null)
		{
			return new Point(Math.max(0, anchor.x - GAP - box.width), Math.max(0, anchor.y));
		}
		return corner(box, canvas);
	}

	/**
	 * Where a one-line message goes: just above the check button's icon, its right edge level with the icon's right
	 * edge (so it grows to the left, over the game, never off the right side); below the icon when there is no room
	 * above; with no icon, the bottom-right corner as for the box (the user, 2026-11-05: "show that text always just
	 * above where the current placement of the button is? even if we drag?").
	 */
	static Point above(Rectangle anchor, Dimension message, Dimension canvas)
	{
		if (anchor == null)
		{
			return corner(message, canvas);
		}
		final int x = Math.max(0, anchor.x + anchor.width - message.width);
		final int y = anchor.y - GAP - message.height;
		return new Point(x, y >= 0 ? y : anchor.y + anchor.height + GAP);
	}

	private static Point corner(Dimension box, Dimension canvas)
	{
		return new Point(Math.max(0, canvas.width - MARGIN - box.width),
			Math.max(0, canvas.height - MARGIN - box.height));
	}
}

package com.inventoryquickcheck;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.function.Supplier;
import net.runelite.client.input.MouseAdapter;

/**
 * Takes the left presses on the check button and runs the check. It never reads the client: the bounds are those of
 * the last drawn frame, because this runs on the AWT thread. A press with Alt held still passes through to RuneLite
 * (the icon is locked to the tab, so that only matters for the box); a right press passes through too, so the game's
 * menu opens with the button's own lines (Configure, Discord).
 * Choice: the click that follows a consumed press is consumed too, and so is the release.
 */
public final class ButtonClicks extends MouseAdapter
{
	private final Supplier<Rectangle> drawn;
	private final Runnable check;
	private boolean pressTaken;
	private boolean clickDue;

	public ButtonClicks(Supplier<Rectangle> drawn, Runnable check)
	{
		this.drawn = drawn;
		this.check = check;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		clickDue = false;
		final Rectangle bounds = drawn.get();
		if (bounds != null && bounds.contains(e.getPoint()) && !e.isAltDown() && e.getButton() == MouseEvent.BUTTON1)
		{
			e.consume();
			pressTaken = true;
			check.run();
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (pressTaken)
		{
			e.consume();
			pressTaken = false;
			clickDue = true;
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (clickDue)
		{
			e.consume();
			clickDue = false;
		}
		return e;
	}
}

package com.inventoryquickcheck;

import java.net.URL;

/**
 * How the check button looks: one picture per choice, shipped as resources. RuneLite's settings dropdown shows an
 * enum through its {@code toString()} in a label, and a label draws text that starts with {@code <html>} as HTML, so
 * each look's text is its small picture followed by its name; the saved setting is the constant's name, so the HTML
 * never reaches the stored config.
 * Choice: a picture that cannot be found leaves the label alone.
 */
public enum ButtonLook
{
	SLATE_CHECK("Slate check", "slate_check"),
	GOLD_RING_CHECK("Gold ring check", "gold_ring_check"),
	TEAL_CHECK("Teal check", "teal_check"),
	SAGE_QUESTION("Sage question", "sage_question"),
	POTION("Potion", "potion"),
	SMILEY("Smiley", "smiley"),
	BACKPACK("Backpack", "backpack"),
	STARBURST("Starburst", "starburst"),
	LIGHTNING("Lightning", "lightning"),
	GOLD_STAR("Gold star", "gold_star"),
	DARK_DOT_TICK("Dark dot tick", "dark_dot_tick"),
	STONE_TABLET("Stone tablet", "stone_tablet"),
	GOLD_COIN("Gold coin", "gold_coin");

	private static final String FOLDER = "/com/inventoryquickcheck/looks/";

	private final String label;
	private final String key;
	private final String menuText;

	ButtonLook(String label, String key)
	{
		this.label = label;
		this.key = key;
		this.menuText = menuText(label(), ButtonLook.class.getResource(smallPicture()));
	}

	/** The plain name of the look. */
	public String label()
	{
		return label;
	}

	/** The resource path of the 24 px picture. */
	public String picture()
	{
		return FOLDER + key + ".png";
	}

	/** The resource path of the 16 px picture. */
	public String smallPicture()
	{
		return FOLDER + key + "_16.png";
	}

	/** The label alone when there is no picture, else the picture then the label as the HTML a settings label shows. */
	static String menuText(String label, URL picture)
	{
		if (picture == null)
		{
			return label;
		}
		return "<html><img src='" + picture + "' width=16 height=16>&nbsp;" + label + "</html>";
	}

	/** The text RuneLite shows in the settings dropdown: the small picture, then the name. */
	@Override
	public String toString()
	{
		return menuText;
	}
}

