package com.inventoryquickcheck;

import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.api.gameval.InterfaceID;

/** Where the check button goes relative to the bank-side inventory's slots. Pure functions; no client. */
final class ButtonSpot
{
	/** The game's row pitch of the inventory, in pixels. */
	private static final int DEFAULT_PITCH = 36;
	/** The game's gap between two inventory slots side by side, in pixels. */
	private static final int DEFAULT_GAP = 6;

	private ButtonSpot()
	{
	}

	/**
	 * The gap between the first slot and the one beside it: the second's left edge minus the first's right edge.
	 * Choice: anything unreadable, or overlapping, gives the game's own 6.
	 */
	static int gap(Rectangle slot0, Rectangle slot1)
	{
		if (slot0 == null || slot1 == null || slot1.x - (slot0.x + slot0.width) < 0)
		{
			return DEFAULT_GAP;
		}
		return slot1.x - (slot0.x + slot0.width);
	}

	/** The small icon's side inside the first slot: half the slot's height (16 at the game's 32). */
	static int smallSize(Rectangle slot0)
	{
		return slot0.height / 2;
	}

	/**
	 * The row pitch: the second row's y minus the first's. Choice: anything unreadable, or not below the first
	 * slot, gives the game's own 36.
	 */
	static int pitch(Rectangle slot0, Rectangle slot4)
	{
		if (slot0 == null || slot4 == null || slot4.y - slot0.y <= 0)
		{
			return DEFAULT_PITCH;
		}
		return slot4.y - slot0.y;
	}

	/** The skills tab above the inventory for a toplevel, or -1 where there is none (modern layouts). */
	static int skillsStoneOf(int toplevel)
	{
		if (toplevel == InterfaceID.TOPLEVEL)
		{
			return InterfaceID.Toplevel.STONE1;
		}
		if (toplevel == InterfaceID.TOPLEVEL_OSRS_STRETCH)
		{
			return InterfaceID.ToplevelOsrsStretch.STONE1;
		}
		return -1;
	}

	/** A tab's centre (either tab) as an offset from the first slot's top left; null when a part or the tab is missing. */
	static Point tabOffset(Rectangle tab, Rectangle slot0)
	{
		if (tab == null || slot0 == null || tab.width <= 0 || tab.height <= 0)
		{
			return null;
		}
		return new Point(tab.x + tab.width / 2 - slot0.x, tab.y + tab.height / 2 - slot0.y);
	}

	/** The size x size square centred on the first slot's top left plus the offset; null when either is null. */
	static Rectangle tabSpot(Rectangle slot0, Point offset, int size)
	{
		if (slot0 == null || offset == null)
		{
			return null;
		}
		return new Rectangle(slot0.x + offset.x - size / 2, slot0.y + offset.y - size / 2, size, size);
	}

	/** The icon's top left above the inventory: on the skills tab's spot given an offset, else over the column. */
	static Point aboveInventory(Rectangle slot0, int pitch, Point skillsOffset, int size)
	{
		final int cx;
		final int cy;
		if (skillsOffset != null)
		{
			cx = slot0.x + skillsOffset.x;
			cy = slot0.y + skillsOffset.y;
		}
		else
		{
			cx = slot0.x + slot0.width / 2;
			cy = slot0.y + slot0.height / 2 - Math.round(1.25f * pitch);
		}
		return new Point(cx - size / 2, cy - size / 2);
	}

	/**
	 * The point the Missing box hangs left of on the modern layout: the first slot's left edge moved two slot columns
	 * left (the pitch of one column is the slot's width plus the gap), the top level with the slot, so the Status Bars
	 * between the inventory and the box do not cover it.
	 */
	static Rectangle leftOfModernInventory(Rectangle slot0, int columnPitch)
	{
		return new Rectangle(slot0.x - 2 * columnPitch, slot0.y, 0, 0);
	}

	/**
	 * The icon's top left inside the first slot: centred half a slot gap left of the slot's left edge, level with its
	 * top edge (the user, 2026-11-08: "middle x of two inv spaces ... roughly where i drew the orange circle").
	 */
	static Point insideFirstSlot(Rectangle slot0, int gap, int size)
	{
		return new Point(slot0.x - gap / 2 - size / 2, slot0.y - size / 2);
	}
}

package com.inventoryquickcheck;

import java.util.Set;

/**
 * What the player carries, read by the caller: 28 inventory ids and amounts and 14 worn ids ({@code -1} empty), and
 * the rune ids in the rune pouch ({@code null} when no rune pouch is carried). Immutable. Choice: public final fields,
 * the arrays copied in, so no accessor only a test would call.
 */
public final class Carried
{
	public final int[] inventoryIds;
	public final int[] inventoryAmounts;
	public final int[] wornIds;
	public final Set<Integer> pouchRunes;

	public Carried(int[] inventoryIds, int[] inventoryAmounts, int[] wornIds, Set<Integer> pouchRunes)
	{
		this.inventoryIds = inventoryIds.clone();
		this.inventoryAmounts = inventoryAmounts.clone();
		this.wornIds = wornIds.clone();
		this.pouchRunes = pouchRunes;
	}
}

package com.inventoryquickcheck;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/** Reads what the player carries from the client. Client thread only. */
public final class CarriedReader
{
	private static final int INVENTORY_SLOTS = 28;
	private static final int WORN_SLOTS = 14;

	private CarriedReader()
	{
	}

	public static Carried read(Client client)
	{
		final int[] ids = new int[INVENTORY_SLOTS];
		final int[] amounts = new int[INVENTORY_SLOTS];
		final int[] worn = new int[WORN_SLOTS];
		fill(client.getItemContainer(InventoryID.INV), ids, amounts);
		fill(client.getItemContainer(InventoryID.WORN), worn, new int[WORN_SLOTS]);

		boolean pouch = false;
		for (final int id : ids)
		{
			pouch |= id == ItemID.BH_RUNE_POUCH || id == ItemID.BH_RUNE_POUCH_TROUVER
				|| id == ItemID.DIVINE_RUNE_POUCH || id == ItemID.DIVINE_RUNE_POUCH_TROUVER;
		}
		Set<Integer> runes = null;
		if (pouch)
		{
			runes = new HashSet<>();
			final EnumComposition table = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			final int[] types = {
				client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1), client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2),
				client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_3), client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_4)};
			for (final int type : types)
			{
				if (type > 0)
				{
					runes.add(table.getIntValue(type));
				}
			}
		}
		return new Carried(ids, amounts, worn, runes);
	}

	private static void fill(ItemContainer container, int[] ids, int[] amounts)
	{
		for (int i = 0; i < ids.length; i++)
		{
			ids[i] = -1;
		}
		if (container == null)
		{
			return;
		}
		final Item[] items = container.getItems();
		for (int i = 0; i < ids.length && i < items.length; i++)
		{
			if (items[i] != null && items[i].getId() != -1)
			{
				ids[i] = items[i].getId();
				amounts[i] = items[i].getQuantity();
			}
		}
	}
}

package com.inventoryquickcheck;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

/**
 * The small icon shown while the bank is open. A detached overlay locked to its place (not movable, snappable or
 * resettable): each frame it puts itself where "Button place" says (above the inventory, inside the first slot, or on
 * the attack tab), read from the bank-side inventory's slots. A spot an older build saved is dropped by RuneLite
 * when the overlay is added. It never saves a place itself. Presses on it are taken by {@link ButtonClicks}, which
 * reads the bounds this class publishes.
 * The picture is the chosen "Button look"'s: its 24 px picture at 24, its 16 px picture at 16, else the 24 px one
 * scaled. The pictures are loaded when the look changes and kept.
 * Choice: the tab is the first of the three toplevel layouts whose attack tab is loaded and not hidden.
 * Choice: a place whose widgets cannot be read falls back to the attack tab's spot.
 */
public final class CheckButton extends Overlay
{
	static final int SIZE = 24;
	private static final int GAP = 4;
	/** The orange name after each of the button's right-click lines: the plugin's display name. */
	private static final String MENU_TARGET = "2h Inventory Setups Quick Check";

	private final Client client;
	private final InventoryQuickCheckConfig config;
	private final TooltipManager tooltipManager;
	private final Supplier<ShownResult> shown;
	/** The look the pictures below were loaded for; client thread only. */
	private ButtonLook loadedLook;
	/** The look's 24 px picture; client thread only. */
	private BufferedImage image;
	/** The look's 16 px picture; client thread only. */
	private BufferedImage smallPicture;
	/** The 24 px picture scaled to an odd size, at the size last asked for; client thread only. */
	private BufferedImage smallImage;
	private volatile Rectangle drawn;
	private volatile Rectangle anchor;
	/** The default spot last asked for; client thread only. */
	private Point lastPlace;
	/** The icon size last drawn; client thread only. */
	private int lastSize;
	/** The attack tab's spot for the box (as {@link #anchor} when no slot is readable); written each frame. */
	private volatile Rectangle attackSpot;
	/** The bank-side inventory's first slot and the one beside it, while the bank is open; written each frame. */
	private volatile Rectangle slot0Now;
	private volatile Rectangle slot1Now;
	/** The bank's outer frame while the bank is open; written each frame. */
	private volatile Rectangle bankFrame;
	/** Whether the resizable modern layout is up; written each frame. */
	private volatile boolean modern;
	/** Whether the fixed layout is up; written each frame. */
	private volatile boolean fixedLayout;
	/** The attack tab's centre as an offset from the first slot, read once per bank opening; client thread only. */
	private Point attackOffset;
	/** The toplevel {@link #attackOffset} was read for; client thread only. */
	private int attackOffsetFor;
	/** The skills tab's centre as an offset from the first slot, read once per bank opening; client thread only. */
	private Point skillsOffset;
	/** The toplevel {@link #skillsOffset} was read for; client thread only. */
	private int skillsOffsetFor;

	/**
	 * The plugin is passed on to RuneLite so that the menu's Configure line opens this plugin's own settings page
	 * (RuneLite's config plugin does the opening, for any overlay that knows its plugin).
	 */
	public CheckButton(Plugin plugin, Client client, InventoryQuickCheckConfig config, TooltipManager tooltipManager,
		Supplier<ShownResult> shown, Runnable outlineColour)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.tooltipManager = tooltipManager;
		this.shown = shown;
		setPosition(OverlayPosition.DETACHED);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// The user, 2026-11-08: it once sat "under another layer of something on the screen and somewhere i didnt
		// expect it"; so it stays on the tab and draws above the other detached overlays.
		setMovable(false);
		setSnappable(false);
		setResettable(false);
		setPriority(PRIORITY_HIGHEST);
		// The user, 2026-11-05 (menu 1 on docs/pictures/menu_sheet.png): right-click shows Configure, Outline colour,
		// Discord.
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, MENU_TARGET);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Outline colour", MENU_TARGET, e ->
		{
			if (outlineColour != null)
			{
				outlineColour.run();
			}
		});
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Discord", MENU_TARGET, e -> LinkBrowser.browse(SupportLinks.DISCORD_URL));
	}

	/** The bounds drawn on the last frame, or null when nothing is drawn. Read by the mouse listener. */
	Rectangle drawn()
	{
		return drawn;
	}

	/**
	 * Where the result box hangs from: the drawn bounds when the icon is drawn; else its default spot on the attack tab;
	 * else null. Worked out each frame on the client thread.
	 */
	Rectangle anchor()
	{
		return anchor;
	}

	/**
	 * Where the result box hangs from for a Box place choice, worked out from the values read on the last frame (on
	 * the client thread): Right of the bank is just right of the bank's frame; Left of the inventory is left of the
	 * attack tab's spot (left of the side panel), or on the modern layout two slot columns left of the first slot.
	 * Automatic and Where I drag it are Right of the bank, but Left of the inventory on the fixed layout. A spot whose widgets cannot be read, and the bank closed, fall
	 * back to the attack tab's spot.
	 * Choice: Hidden is never drawn, so it gets the attack tab's spot too.
	 */
	BoxAnchor boxSpot(MissingBoxPlace place)
	{
		final MissingBoxPlace rule = MissingBoxPlace.forLayout(place, fixedLayout);
		final Rectangle bank = bankFrame;
		if (rule == MissingBoxPlace.RIGHT_OF_BANK && bank != null)
		{
			return BoxAnchor.rightOf(bank);
		}
		final Rectangle slot0 = slot0Now;
		if (rule == MissingBoxPlace.LEFT_OF_INVENTORY && modern && slot0 != null)
		{
			final int pitch = slot0.width + ButtonSpot.gap(slot0, slot1Now);
			return BoxAnchor.beside(ButtonSpot.leftOfModernInventory(slot0, pitch));
		}
		return BoxAnchor.beside(attackSpot);
	}

	/** Reads and keeps what {@link #boxSpot} needs for this frame. */
	private void publish(Rectangle attack, boolean bankOpen)
	{
		attackSpot = attack;
		final int toplevel = client.getTopLevelInterfaceId();
		modern = toplevel == InterfaceID.TOPLEVEL_PRE_EOC;
		fixedLayout = toplevel == InterfaceID.TOPLEVEL;
		slot0Now = bankOpen ? slotBounds(0) : null;
		slot1Now = bankOpen ? slotBounds(1) : null;
		final Widget frame = bankOpen ? client.getWidget(InterfaceID.Bankmain.FRAME) : null;
		final Rectangle bounds = frame == null || frame.isHidden() ? null : frame.getBounds();
		bankFrame = bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : bounds;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!shouldDraw(BankState.isOpen(client), config.showButton()))
		{
			drawn = null;
			skillsOffset = null;
			attackOffset = null;
			final Point tabSpot = spot(tabBounds(), null, null, SIZE, SIZE);
			anchor = tabSpot == null ? null : new Rectangle(tabSpot.x, tabSpot.y, SIZE, SIZE);
			publish(anchor, false);
			return null;
		}
		// The renderer has already translated the graphics to this point (clamped to the screen).
		final Point at = getBounds().getLocation();
		final Point tabPlace = spot(tabBounds(), itemsBounds(), null, SIZE, SIZE);
		final Rectangle slotIcon = slotSpot(config.buttonPlace());
		final int size = slotIcon == null ? SIZE : slotIcon.width;
		final Point place = slotIcon == null ? tabPlace : slotIcon.getLocation();
		if (place == null)
		{
			drawn = null;
			anchor = null;
			publish(attackSpotOf(tabPlace, null), true);
			lastPlace = null;
			return null;
		}
		if (!place.equals(lastPlace) || size != lastSize)
		{
			// A new spot or size: move there and draw from the next frame, so the picture and the click area agree.
			lastPlace = place;
			lastSize = size;
			getBounds().setLocation(place);
			drawn = null;
			anchor = new Rectangle(place.x, place.y, size, size);
			publish(attackSpotOf(tabPlace, anchor), true);
			return new Dimension(size, size);
		}
		loadLook(config.buttonLook());
		graphics.drawImage(pictureFor(size), 0, 0, null);
		final Rectangle now = new Rectangle(at.x, at.y, size, size);
		drawn = now;
		anchor = now;
		publish(attackSpotOf(tabPlace, now), true);
		final net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && now.contains(mouse.getX(), mouse.getY()))
		{
			final ShownResult result = shown.get();
			tooltipManager.add(new Tooltip(tooltip(result == null ? null : result.hint())));
		}
		return new Dimension(size, size);
	}

	/**
	 * The attack-tab spot for the box while the bank is open: the live first slot plus the attack tab's offset (read once
	 * per opening); else the live attack-tab spot; else the button's own bounds.
	 */
	private Rectangle attackSpotOf(Point tabPlace, Rectangle own)
	{
		final int toplevel = client.getTopLevelInterfaceId();
		final Rectangle slot0 = slotBounds(0);
		if (slot0 != null && (attackOffset == null || attackOffsetFor != toplevel))
		{
			// The hidden tab's bounds go stale on a resize, so its centre is read once per opening.
			attackOffset = ButtonSpot.tabOffset(tabBounds(), slot0);
			attackOffsetFor = toplevel;
		}
		final Rectangle fromSlot = ButtonSpot.tabSpot(slot0, attackOffset, SIZE);
		if (fromSlot != null)
		{
			return fromSlot;
		}
		return tabPlace == null ? own : new Rectangle(tabPlace.x, tabPlace.y, SIZE, SIZE);
	}

	/**
	 * The icon's bounds for the chosen place, from the bank-side inventory's first slot and its neighbours (the one
	 * beside it for the gap, the one below it for the row pitch); null for the attack tab or when the slots cannot be
	 * read.
	 */
	private Rectangle slotSpot(ButtonPlace choice)
	{
		if (choice == ButtonPlace.ATTACK_TAB)
		{
			return null;
		}
		final Rectangle slot0 = slotBounds(0);
		if (slot0 == null)
		{
			return null;
		}
		if (choice == ButtonPlace.INSIDE_FIRST_SLOT)
		{
			final int small = ButtonSpot.smallSize(slot0);
			final Point at = ButtonSpot.insideFirstSlot(slot0, ButtonSpot.gap(slot0, slotBounds(1)), small);
			return new Rectangle(at.x, at.y, small, small);
		}
		final int toplevel = client.getTopLevelInterfaceId();
		final int stone = ButtonSpot.skillsStoneOf(toplevel);
		if (stone != -1 && (skillsOffset == null || skillsOffsetFor != toplevel))
		{
			// The hidden tab's bounds go stale on a resize, so its centre is read once per opening.
			skillsOffset = ButtonSpot.tabOffset(stoneBounds(stone), slot0);
			skillsOffsetFor = toplevel;
		}
		final Point at = ButtonSpot.aboveInventory(slot0, ButtonSpot.pitch(slot0, slotBounds(4)),
			stone == -1 ? null : skillsOffset, SIZE);
		return new Rectangle(at.x, at.y, SIZE, SIZE);
	}

	/** Loads the chosen look's pictures when the look has changed; a change shows on the next frame. */
	private void loadLook(ButtonLook look)
	{
		if (look == loadedLook)
		{
			return;
		}
		loadedLook = look;
		image = ImageUtil.loadImageResource(CheckButton.class, look.picture());
		smallPicture = ImageUtil.loadImageResource(CheckButton.class, look.smallPicture());
		smallImage = null;
	}

	/** The picture for a size: the 24 px one, the 16 px one, or the 24 px one scaled (kept until the size changes). */
	private BufferedImage pictureFor(int size)
	{
		if (size == SIZE)
		{
			return image;
		}
		if (size == smallPicture.getWidth())
		{
			return smallPicture;
		}
		if (smallImage == null || smallImage.getWidth() != size)
		{
			smallImage = ImageUtil.resizeImage(image, size, size);
		}
		return smallImage;
	}

	/** A slot of the bank-side inventory, or null when missing or empty-sized. */
	private Rectangle slotBounds(int index)
	{
		final Widget items = client.getWidget(InterfaceID.Bankside.ITEMS);
		final Widget slot = items == null ? null : items.getChild(index);
		final Rectangle bounds = slot == null ? null : slot.getBounds();
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : bounds;
	}

	/** The hover text: Check setup, then the hint's rows when a no-setup result is up. */
	static String tooltip(String hint)
	{
		return hint == null ? "Check setup" : "Check setup</br>" + hint;
	}

	/** Whether the icon is drawn at all. */
	static boolean shouldDraw(boolean bankOpen, boolean setting)
	{
		return bankOpen && setting;
	}

	/**
	 * Where the icon's top left goes: the saved point; else centred on the tab; else left of the bank-side items; else
	 * null (not drawn). This is the attack-tab spot: the Button place choice "Attack tab", the fallback of the other
	 * places, and the anchor while the bank is closed.
	 */
	static Point spot(Rectangle tab, Rectangle banksideItems, Point saved, int w, int h)
	{
		if (saved != null)
		{
			return saved;
		}
		if (tab != null)
		{
			return new Point(tab.x + (tab.width - w) / 2, tab.y + (tab.height - h) / 2);
		}
		if (banksideItems != null)
		{
			return new Point(banksideItems.x - GAP - w, banksideItems.y);
		}
		return null;
	}

	/**
	 * The attack tab of the layout in use. The game hides the tab's own widget while the bank is open (the stones seen
	 * then are the strip behind it), so its place is read whether hidden or not.
	 */
	private Rectangle tabBounds()
	{
		return stoneBounds(stoneOf(client.getTopLevelInterfaceId()));
	}

	/** A tab's bounds, read whether hidden or not; null for -1, a missing widget or an off-screen or empty bound. */
	private Rectangle stoneBounds(int stone)
	{
		if (stone == -1)
		{
			return null;
		}
		final Widget widget = client.getWidget(stone);
		if (widget == null)
		{
			return null;
		}
		final Rectangle bounds = widget.getBounds();
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 || bounds.x < 0 || bounds.y < 0 ? null : bounds;
	}

	/** The attack tab's widget for a toplevel interface, or -1 for one without tabs. */
	static int stoneOf(int toplevel)
	{
		if (toplevel == InterfaceID.TOPLEVEL)
		{
			return InterfaceID.Toplevel.STONE0;
		}
		if (toplevel == InterfaceID.TOPLEVEL_OSRS_STRETCH)
		{
			return InterfaceID.ToplevelOsrsStretch.STONE0;
		}
		if (toplevel == InterfaceID.TOPLEVEL_PRE_EOC)
		{
			return InterfaceID.ToplevelPreEoc.STONE0;
		}
		return -1;
	}

	private Rectangle itemsBounds()
	{
		final Widget widget = client.getWidget(InterfaceID.Bankside.ITEMS);
		return widget == null ? null : widget.getBounds();
	}
}

package com.inventoryquickcheck;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.SortedSet;
import java.util.TreeSet;

/** The outcome of a check: the inventory slots holding low potions and what is wrong, one entry per thing. */
public final class CheckResult
{
	/** What kind of wrong an entry is. */
	public enum Kind
	{
		MISSING,
		NOT_WORN,
		NOT_IN_POUCH
	}

	/**
	 * One thing wrong: its kind, the item to picture, how many are missing (1 unless a missing group), its name, the
	 * item ids that answer it and whether it is a dose group (the bank number picks the strongest of those).
	 */
	public static final class Entry
	{
		public final Kind kind;
		public final int itemId;
		public final int count;
		public final String name;
		public final Set<Integer> accepts;
		public final boolean dose;

		Entry(Kind kind, int itemId, int count, String name, Set<Integer> accepts, boolean dose)
		{
			this.accepts = Collections.unmodifiableSet(new TreeSet<>(accepts));
			this.dose = dose;
			this.kind = kind;
			this.itemId = itemId;
			this.count = count;
			this.name = name;
		}
	}

	private final SortedSet<Integer> lowSlots;
	private final List<Entry> entries;

	CheckResult(SortedSet<Integer> lowSlots, List<Entry> entries)
	{
		this.lowSlots = Collections.unmodifiableSortedSet(new TreeSet<>(lowSlots));
		this.entries = Collections.unmodifiableList(new ArrayList<>(entries));
	}

	/** Inventory slot indexes holding a potion with fewer doses than the setup wants. */
	public SortedSet<Integer> lowSlots()
	{
		return lowSlots;
	}

	/** Everything missing, not worn or not in the rune pouch, uncut: missing by first setup slot, worn by slot, runes by setup order. */
	public List<Entry> entries()
	{
		return entries;
	}

	/** Whether nothing is wrong: no entries and no low slots. */
	public boolean allGood()
	{
		return entries.isEmpty() && lowSlots.isEmpty();
	}
}

package com.inventoryquickcheck;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/** The rule engine: compares a saved setup with what is carried and says what is wrong. Pure; touches no client. */
public final class Checker
{
	private Checker()
	{
	}

	/** One thing the setup wants: a base (fuzzy and dose items) or an exact id, with how many places and their doses. */
	private static final class Group
	{
		final int firstId;
		final boolean dose;
		final boolean stackable;
		boolean byBase;
		int wanted;
		final List<Integer> wantedDoses = new ArrayList<>();
		int filled;
		final List<int[]> carriedDoses = new ArrayList<>();

		Group(int firstId, boolean dose, boolean stackable)
		{
			this.firstId = firstId;
			this.dose = dose;
			this.stackable = stackable;
		}
	}

	public static CheckResult check(SavedSetup setup, Carried carried, ItemFacts facts)
	{
		final TreeSet<Integer> lowSlots = new TreeSet<>();
		final List<CheckResult.Entry> entries = new ArrayList<>();

		// Inventory groups, order ignored. The map keeps insertion order, which is first-setup-slot order.
		final Map<String, Group> groups = new LinkedHashMap<>();
		for (final SetupItem item : setup.inventory())
		{
			if (item == null)
			{
				continue;
			}
			final boolean dose = Doses.isDoseItem(item.id, facts);
			final String key = dose || item.fuzzy ? "b:" + facts.base(item.id) : "e:" + item.id;
			Group group = groups.get(key);
			if (group == null)
			{
				group = new Group(item.id, dose, !dose && facts.stackable(item.id));
				group.byBase = dose || item.fuzzy;
				groups.put(key, group);
			}
			if (group.stackable)
			{
				group.wanted = 1;
			}
			else
			{
				group.wanted++;
				if (group.dose)
				{
					group.wantedDoses.add(Doses.dose(facts.name(item.id)));
				}
			}
		}

		// Fill from what is carried, in slot order.
		for (int slot = 0; slot < carried.inventoryIds.length; slot++)
		{
			final int id = carried.inventoryIds[slot];
			if (id == -1)
			{
				continue;
			}
			Group group = groups.get("e:" + id);
			if (group == null)
			{
				group = groups.get("b:" + facts.base(id));
			}
			if (group == null)
			{
				// A potion the setup does not list is outlined when it is not full (the user, 2026-11-08, option 1).
				if (LowPotions.isLow(id, facts))
				{
					lowSlots.add(slot);
				}
				continue;
			}
			if (group.dose)
			{
				group.carriedDoses.add(new int[]{slot, Doses.dose(facts.name(id))});
			}
			else if (group.filled < group.wanted)
			{
				group.filled++;
			}
		}
		for (final Group group : groups.values())
		{
			if (!group.dose)
			{
				continue;
			}
			// Every carried potion below the strongest dose the setup wants is low, spares included (the user,
			// 2026-11-04: "mark all low").
			group.filled = Math.min(group.carriedDoses.size(), group.wantedDoses.size());
			final int full = Collections.max(group.wantedDoses);
			for (final int[] have : group.carriedDoses)
			{
				if (have[1] < full)
				{
					lowSlots.add(have[0]);
				}
			}
		}

		// A rune the setup wants loose counts when the carried pouch holds it.
		if (carried.pouchRunes != null)
		{
			for (final Group group : groups.values())
			{
				if (group.stackable && group.filled < group.wanted && carried.pouchRunes.contains(group.firstId))
				{
					group.filled = group.wanted;
				}
			}
		}

		// Missing, by first setup slot.
		for (final Group group : groups.values())
		{
			final int missing = group.wanted - group.filled;
			if (missing <= 0)
			{
				continue;
			}
			final String name = group.dose
				? Doses.withoutDose(facts.name(group.firstId)) : facts.name(group.firstId);
			final Set<Integer> accepts = group.byBase
				? new TreeSet<>(facts.variations(group.firstId)) : new TreeSet<>(Collections.singleton(group.firstId));
			entries.add(new CheckResult.Entry(CheckResult.Kind.MISSING, group.firstId, missing, name, accepts,
				group.dose));
		}

		// Worn.
		final List<SetupItem> equipment = setup.equipment();
		for (int slot = 0; slot < equipment.size(); slot++)
		{
			final SetupItem item = equipment.get(slot);
			if (item == null)
			{
				continue;
			}
			final int worn = slot < carried.wornIds.length ? carried.wornIds[slot] : -1;
			final boolean ok = worn != -1
				&& (item.fuzzy ? facts.base(worn) == facts.base(item.id) : worn == item.id);
			if (!ok)
			{
				final Set<Integer> accepts = item.fuzzy
					? new TreeSet<>(facts.variations(item.id)) : new TreeSet<>(Collections.singleton(item.id));
				accepts.add(item.id);
				entries.add(new CheckResult.Entry(CheckResult.Kind.NOT_WORN, item.id, 1, facts.name(item.id), accepts,
					false));
			}
		}

		// Rune pouch.
		if (setup.runePouch() != null && carried.pouchRunes != null)
		{
			for (final int rune : setup.runePouch())
			{
				if (!carried.pouchRunes.contains(rune) && !carriedLoose(carried, rune))
				{
					entries.add(new CheckResult.Entry(CheckResult.Kind.NOT_IN_POUCH, rune, 1, facts.name(rune),
					new TreeSet<>(Collections.singleton(rune)), false));
				}
			}
		}

		// Equipment, non-consumables, others, consumables; a stable sort keeps the order inside a group.
		final Map<CheckResult.Entry, Integer> groupOf = new IdentityHashMap<>();
		for (final CheckResult.Entry entry : entries)
		{
			groupOf.put(entry, sortGroup(entry, facts));
		}
		entries.sort((a, b) -> Integer.compare(groupOf.get(a), groupOf.get(b)));

		return new CheckResult(lowSlots, entries);
	}

	private static boolean carriedLoose(Carried carried, int id)
	{
		for (final int have : carried.inventoryIds)
		{
			if (have == id)
			{
				return true;
			}
		}
		return false;
	}

	/** 1 equipment, 2 non-consumables, 3 others (stackables), 4 consumables. */
	private static int sortGroup(CheckResult.Entry entry, ItemFacts facts)
	{
		if (entry.kind == CheckResult.Kind.NOT_WORN || facts.equipable(entry.itemId))
		{
			return 1;
		}
		if (facts.consumable(entry.itemId))
		{
			return 4;
		}
		return facts.stackable(entry.itemId) ? 3 : 2;
	}
}

package com.inventoryquickcheck;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/** Item facts from the client's item data. Client thread only. */
public final class ClientItemFacts implements ItemFacts
{
	private final ItemManager itemManager;
	private final Map<Integer, String> names = new HashMap<>();
	private final Map<Integer, Boolean> equipables = new HashMap<>();
	private final Map<Integer, Boolean> consumables = new HashMap<>();

	public ClientItemFacts(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	@Override
	public String name(int id)
	{
		String name = names.get(id);
		if (name == null)
		{
			name = itemManager.getItemComposition(id).getName();
			names.put(id, name);
		}
		return name;
	}

	@Override
	public int base(int id)
	{
		return ItemVariationMapping.map(id);
	}

	/**
	 * RuneLite keys the variation groups by their base id, so the group is looked up through {@link #base}: asked with
	 * Prayer potion(3) directly it answers only Prayer potion(3), and no potion would ever look low (the user,
	 * 2026-11-05: "still no flashing on the pots that are not full").
	 */
	@Override
	public Collection<Integer> variations(int id)
	{
		final Collection<Integer> out = new ArrayList<>(ItemVariationMapping.getVariations(ItemVariationMapping.map(id)));
		if (!out.contains(id))
		{
			out.add(id);
		}
		return out;
	}

	@Override
	public boolean stackable(int id)
	{
		return itemManager.getItemComposition(id).isStackable();
	}

	@Override
	public boolean equipable(int id)
	{
		return cached(equipables, id, "Wear", "Wield", "Equip");
	}

	@Override
	public boolean consumable(int id)
	{
		return cached(consumables, id, "Eat", "Drink");
	}

	private boolean cached(Map<Integer, Boolean> cache, int id, String... actions)
	{
		Boolean found = cache.get(id);
		if (found == null)
		{
			found = false;
			final String[] have = itemManager.getItemComposition(id).getInventoryActions();
			if (have != null)
			{
				for (final String action : have)
				{
					for (final String wanted : actions)
					{
						if (wanted.equals(action))
						{
							found = true;
						}
					}
				}
			}
			cache.put(id, found);
		}
		return found;
	}
}

package com.inventoryquickcheck;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.inventoryquickcheck;

/**
 * The outline colour preview: for a few seconds after the colour or thickness setting is saved, every potion carried
 * is outlined so the player can judge the choice. Pure: no client.
 */
final class ColourPreview
{
	static final long SHOW_MS = 5000;

	private ColourPreview()
	{
	}

	/** True while the preview that started at {@code startMs} (-1 for none) is still on. */
	static boolean showing(long startMs, long nowMs)
	{
		return startMs >= 0 && nowMs - startMs >= 0 && nowMs - startMs < SHOW_MS;
	}

	/** True for the two settings whose change starts a preview. */
	static boolean previews(String group, String key)
	{
		return "inventoryquickcheck".equals(group) && ("markColour".equals(key) || "markThickness".equals(key));
	}
}

package com.inventoryquickcheck;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads the dose count a potion's name ends with, as in {@code Saradomin brew(3)}. */
public final class Doses
{
	private static final Pattern TRAILING = Pattern.compile("\\s*\\((\\d+)\\)\\s*$");

	private Doses()
	{
	}

	/** The number in a trailing {@code (n)}, spaces allowed before the bracket; -1 when there is none. */
	public static int dose(String name)
	{
		final Matcher matcher = TRAILING.matcher(name);
		return matcher.find() ? Integer.parseInt(matcher.group(1)) : -1;
	}

	/** Whether {@code id} is a potion-like item: it has a dose and none of its variations has a dose above 4. */
	public static boolean isDoseItem(int id, ItemFacts facts)
	{
		if (dose(facts.name(id)) <= 0)
		{
			return false;
		}
		for (final int variation : facts.variations(id))
		{
			if (dose(facts.name(variation)) > 4)
			{
				return false;
			}
		}
		return true;
	}

	/** The name without its trailing {@code (n)} and the spaces before it. */
	public static String withoutDose(String name)
	{
		return TRAILING.matcher(name).replaceFirst("");
	}
}

package com.inventoryquickcheck;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

