import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * The one-line answers - All good and the two setup messages in {@link Texts} - in a small label just
 * above the check button's icon, its right edge level with the icon's, wherever the icon is (the user, 2026-11-05:
 * "show that text always just above where the current placement of the button is? even if we drag?"). It follows the
 * icon and cannot be dragged on its own. The list of pictures stays {@link ResultOverlay}'s.
 */
public final class MessageOverlay extends Overlay
{
	private static final int PADDING = 4;

	private final Supplier<ShownResult> shown;
	private final InventoryQuickCheckConfig config;
	private final Supplier<Rectangle> anchor;
	private final Client client;
	/** The place last asked for; render thread only. */
	private Point lastPlace;

	public MessageOverlay(Supplier<ShownResult> shown, InventoryQuickCheckConfig config, Supplier<Rectangle> anchor,
		Client client)
	{
		this.shown = shown;
		this.config = config;
		this.anchor = anchor;
		this.client = client;
		setPosition(OverlayPosition.DETACHED);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(false);
		setResettable(false);
		setSnappable(false);
	}

	@Override
	public String getName()
	{
		return "InventoryQuickCheckMessage";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final ShownResult result = shown.get();
		if (result == null || result.message() == null || !result.rows().isEmpty()
			|| ResultOverlay.over(result, System.currentTimeMillis(), config.secondsToShow(), BankState.isOpen(client))
			|| !ResultOverlay.showsBox(BankState.isOpen(client), config.hotkeyBoxWhenBankClosed()))
		{
			return null;
		}
		final FontMetrics metrics = graphics.getFontMetrics();
		final Dimension size = new Dimension(metrics.stringWidth(result.message()) + 2 * PADDING,
			metrics.getAscent() + metrics.getDescent() + 2 * PADDING);
		final Point place = BoxPlace.above(anchor.get(), size,
			new Dimension(client.getCanvasWidth(), client.getCanvasHeight()));
		if (!place.equals(lastPlace))
		{
			// A new place (the icon moved, or the text changed): move there and draw from the next frame.
			lastPlace = place;
			getBounds().setLocation(place);
			return size;
		}
		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fillRect(0, 0, size.width, size.height);
		ResultOverlay.text(graphics, result.message(), result.messageColour(), PADDING, PADDING + metrics.getAscent());
		return size;
	}
}

package com.inventoryquickcheck;

/** Where the Missing box sits. */
public enum MissingBoxPlace
{
	AUTOMATIC("Automatic"),
	LEFT_OF_INVENTORY("Left of the inventory"),
	RIGHT_OF_BANK("Right of the bank"),
	WHERE_I_DRAG("Where I drag it"),
	HIDDEN("Hidden");

	private final String label;

	MissingBoxPlace(String label)
	{
		this.label = label;
	}

	/** The label RuneLite shows in the settings. */
	@Override
	public String toString()
	{
		return label;
	}

	/** The choice after a drag: Where I drag it for Automatic, Left and Right; else null (no change). */
	static MissingBoxPlace afterDrag(MissingBoxPlace now)
	{
		if (now == AUTOMATIC || now == LEFT_OF_INVENTORY || now == RIGHT_OF_BANK)
		{
			return WHERE_I_DRAG;
		}
		return null;
	}

	/**
	 * The choice after the dragged spot is reset: from Where I drag it, the choice from before when that was Automatic,
	 * Left or Right, else Automatic; null (no change) for any other current choice.
	 */
	static MissingBoxPlace afterReset(MissingBoxPlace now, MissingBoxPlace before)
	{
		if (now != WHERE_I_DRAG)
		{
			return null;
		}
		if (before == AUTOMATIC || before == LEFT_OF_INVENTORY || before == RIGHT_OF_BANK)
		{
			return before;
		}
		return AUTOMATIC;
	}

	/**
	 * The spot rule a choice uses on a layout: Automatic and Where I drag it (until dragged) are right of the bank, but
	 * left of the inventory on the fixed layout, where the bank leaves no room beside it (the user, 2026-11-08: "id like
	 * the default settings for fixed resizable layout to also the beside the bank one we are using for modern"); the
	 * rest as they are.
	 */
	static MissingBoxPlace forLayout(MissingBoxPlace place, boolean fixedLayout)
	{
		if (place == AUTOMATIC || place == WHERE_I_DRAG)
		{
			return fixedLayout ? LEFT_OF_INVENTORY : RIGHT_OF_BANK;
		}
		return place;
	}
}

package com.inventoryquickcheck;

import java.awt.Canvas;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GraphicsConfiguration;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

/**
 * Opens RuneLite's own colour picker (alpha hidden) for the outline colour, so the potions can be recoloured live: it
 * reports every move of the reader's hand and tells when it closes. It opens at the game canvas's top left plus 10 px,
 * kept on the screen, so it does not cover the inventory.
 * Choice: with no manager, no canvas or no picker, nothing opens.
 */
final class OutlinePicker
{
	private static final int OFFSET = 10;

	private final ColorPickerManager manager;
	private final Client client;

	OutlinePicker(ColorPickerManager manager, Client client)
	{
		this.manager = manager;
		this.client = client;
	}

	/** Opens the picker on the Swing thread; {@code live} hears every move, {@code done} hears the colour at close. */
	void open(Color start, Consumer<Color> live, Consumer<Color> done)
	{
		SwingUtilities.invokeLater(() ->
		{
			final Canvas canvas = client.getCanvas();
			if (manager == null || canvas == null)
			{
				return;
			}
			final RuneliteColorPicker picker = manager.create(client, start, "Outline colour", true);
			if (picker == null)
			{
				return;
			}
			picker.setOnColorChange(live);
			picker.setOnClose(done);
			final GraphicsConfiguration screen = canvas.getGraphicsConfiguration();
			if (canvas.isShowing() && screen != null)
			{
				picker.setLocation(spot(new Rectangle(canvas.getLocationOnScreen(), canvas.getSize()), picker.getSize(),
					screen.getBounds()));
			}
			picker.setVisible(true);
		});
	}

	/** The picker's top left: the canvas's top left plus 10 px, each coordinate clamped to keep it on the screen. */
	static Point spot(Rectangle canvasOnScreen, Dimension picker, Rectangle screen)
	{
		final int x = Math.max(screen.x, Math.min(canvasOnScreen.x + OFFSET, screen.x + screen.width - picker.width));
		final int y = Math.max(screen.y, Math.min(canvasOnScreen.y + OFFSET, screen.y + screen.height - picker.height));
		return new Point(x, y);
	}
}

package com.inventoryquickcheck;

import java.awt.Color;

/**
 * How many times the outline on potions flashes after a check. A flash is one off-then-on (the user, 2026-11-11:
 * "perhaps we should consider a flash as an off on action?"), so Steady never goes off and 1 flash is the look the
 * plugin always had. RuneLite's settings dropdown shows an enum through its {@code toString()} in a label that draws
 * HTML, so each choice shows as a small bar of its pattern, in the outline colour (the user, 2026-11-12), then its
 * name; the saved setting is the constant's name. The bar is a row of coloured table cells, since a picture file
 * cannot change colour.
 */
public enum PotionFlashes
{
	STEADY("Steady", 0),
	ONE("1 flash", 1),
	TWO("2 flashes", 2),
	THREE("3 flashes", 3),
	FIVE("5 flashes", 5),
	KEEP_FLASHING("Nonstop", -1);

	private static final int BAR_WIDTH = 42;
	private static final int LIT_WIDTH = 4;
	private static final int DARK_WIDTH = 3;
	private static final int KEEP_FLASHING_CYCLES = BAR_WIDTH / (LIT_WIDTH + DARK_WIDTH);
	private static final String DARK = "#505050";

	/** The outline colour the bars are drawn in; the plugin sets it from the settings. */
	private static volatile Color colour = Color.RED;

	private final String label;
	private final int count;

	PotionFlashes(String label, int count)
	{
		this.label = label;
		this.count = count;
	}

	/** Draws the bars in this colour from now on. */
	public static void useColour(Color outline)
	{
		colour = outline;
	}

	/** The plain name of the choice. */
	public String label()
	{
		return label;
	}

	/** How many off-then-on flashes; negative for Nonstop. */
	public int count()
	{
		return count;
	}

	/** The bar's cell widths in pixels, lit first and then turn about, {@value #BAR_WIDTH} in all. */
	int[] runs()
	{
		final int cycles = count < 0 ? KEEP_FLASHING_CYCLES : count;
		final int tail = BAR_WIDTH - cycles * (LIT_WIDTH + DARK_WIDTH);
		final int[] runs = new int[cycles * 2 + (tail > 0 ? 1 : 0)];
		for (int i = 0; i < cycles; i++)
		{
			runs[i * 2] = LIT_WIDTH;
			runs[i * 2 + 1] = DARK_WIDTH;
		}
		if (tail > 0)
		{
			runs[runs.length - 1] = tail;
		}
		return runs;
	}

	/** The settings-list text: the pattern bar in this colour, then the name. */
	String menuText(Color lit)
	{
		final String litHex = String.format("#%02x%02x%02x", lit.getRed(), lit.getGreen(), lit.getBlue());
		final StringBuilder text = new StringBuilder("<html><table cellpadding=0 cellspacing=0 border=0><tr>"
			+ "<td valign=middle><table cellpadding=0 cellspacing=0 border=0 style='font-size:6px'><tr>");
		final int[] runs = runs();
		for (int i = 0; i < runs.length; i++)
		{
			text.append("<td bgcolor=").append(i % 2 == 0 ? litHex : DARK).append(" width=").append(runs[i])
				.append("></td>");
		}
		return text.append("</tr></table></td><td>&nbsp;").append(label()).append("</td></tr></table></html>")
			.toString();
	}

	/** The text RuneLite shows in the settings dropdown: the bar in the outline colour, then the name. */
	@Override
	public String toString()
	{
		return menuText(colour);
	}
}

package com.inventoryquickcheck;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.util.List;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * The box with the answer: a grid of item pictures with {@code x<k>} beside each, wrapped by the Box layout setting.
 * Its default place is the Box place setting's (the spot the button works out for the choice); the player may
 * Alt+drag it elsewhere (RuneLite then places it, and the plugin switches the setting to Where I drag it) and
 * Alt+right-click it back. Hidden draws no box and locks it (not movable or resettable); it is never snappable.
 * Its right edge holds still as it shrinks (the user,
 * 2026-11-05: "take the rightmost column location when we collapse it"): for one check the overlay keeps the width of
 * its widest moment and draws the box against that width's right edge, the space to its left left clear - so it
 * works wherever RuneLite pins the overlay's top-left corner. It never saves a place itself.
 * A check from the hotkey hides itself, and clears the plugin's result, when the seconds to show are up; a check from
 * the button stays until the plugin clears it (the bank closing).
 */
public final class ResultOverlay extends Overlay
{
	private static final int PADDING = 4;
	private static final int PICTURE_WIDTH = 36;
	private static final int PICTURE_HEIGHT = 32;
	private static final int ROW_HEIGHT = 36;
	private static final Color TITLE_COLOUR = new Color(255, 152, 31);
	private static final int TITLE_PADDING = 8;
	private static final int GAP = 4;
	private static final int TEXT_WIDTH = 26;
	private static final int COLUMN_WIDTH = PICTURE_WIDTH + GAP + TEXT_WIDTH;

	private final Supplier<ShownResult> shown;
	private final Runnable clear;
	private final InventoryQuickCheckConfig config;
	private final Function<MissingBoxPlace, BoxAnchor> boxSpot;
	private final Client client;
	/** The default place last asked for; render thread only. */
	private Point lastPlace;
	/** The widest the box has been for the check that started at {@link #widestFor}; render thread only. */
	private int widest;
	private long widestFor = Long.MIN_VALUE;

	public ResultOverlay(Supplier<ShownResult> shown, Runnable clear, InventoryQuickCheckConfig config,
		Function<MissingBoxPlace, BoxAnchor> boxSpot, Client client)
	{
		this.shown = shown;
		this.clear = clear;
		this.config = config;
		this.boxSpot = boxSpot;
		this.client = client;
		setPosition(OverlayPosition.DETACHED);
		apply(config.boxPlace());
	}

	/** Whether the box may be dragged: every choice but Hidden. */
	static boolean movable(MissingBoxPlace place)
	{
		return place != MissingBoxPlace.HIDDEN;
	}

	/** Locks or frees the box for a Box place choice. */
	void apply(MissingBoxPlace place)
	{
		final boolean free = movable(place);
		setMovable(free);
		setSnappable(false);
		setResettable(free);
	}

	/**
	 * A name of its own, so a place RuneLite saved for the box is never loaded from another overlay.
	 */
	@Override
	public String getName()
	{
		return "InventoryQuickCheckBox";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final ShownResult result = shown.get();
		if (result == null)
		{
			return null;
		}
		if (over(result, System.currentTimeMillis(), config.secondsToShow(), BankState.isOpen(client)))
		{
			// The bank has closed (go this frame, not on the next game tick, which stays as the backstop), or a hotkey
			// check's time is up.
			clear.run();
			return null;
		}
		if (!showsBox(BankState.isOpen(client), config.hotkeyBoxWhenBankClosed()))
		{
			return null;
		}
		// The one-line messages (All good, the setup messages) are MessageOverlay's, above the icon.
		final List<ShownResult.Row> rows = result.rows();
		if (rows.isEmpty() || config.boxPlace() == MissingBoxPlace.HIDDEN)
		{
			return null;
		}
		final Dimension size = gridSize(graphics.getFontMetrics(), rows.size(), config.boxLayout());
		if (widestFor != result.startMs())
		{
			widestFor = result.startMs();
			widest = 0;
		}
		widest = Math.max(widest, size.width);
		final Dimension frame = new Dimension(widest, size.height);
		if (getPreferredLocation() == null)
		{
			final Dimension canvas = new Dimension(client.getCanvasWidth(), client.getCanvasHeight());
			final BoxAnchor hang = boxSpot.apply(config.boxPlace());
			// Choice: no spot (null) is the canvas corner, as before.
			final Point place = hang == null ? BoxPlace.of(null, frame, canvas) : hang.place(frame, canvas);
			if (!place.equals(lastPlace))
			{
				// A new place (the icon moved, or the box grew): move there and draw from the next frame, so the box
				// lands where it is placed.
				lastPlace = place;
				getBounds().setLocation(place);
				return frame;
			}
		}
		else
		{
			// RuneLite places a dragged box; after its reset the default place must be set afresh.
			lastPlace = null;
		}
		// The box against the frame's right edge; the space to its left stays clear.
		final int shift = frame.width - size.width;
		graphics.translate(shift, 0);
		drawGrid(graphics, rows, config.boxLayout());
		graphics.translate(-shift, 0);
		return frame;
	}

	/**
	 * Whether a shown result is over: it started at the bank and the bank is closed, or it came from the hotkey and its
	 * seconds are up (a check from the button stays until the bank closes).
	 */
	static boolean over(ShownResult result, long nowMs, int secondsToShow, boolean bankOpen)
	{
		if (result.startedAtBank() && !bankOpen)
		{
			return true;
		}
		return !result.fromButton() && nowMs - result.startMs() >= secondsToShow * 1000L;
	}

	/**
	 * Whether the box and its one-line messages show: always with the bank open; with it closed (a hotkey check) only
	 * when the setting asks, else the potion outlines are the whole answer (the user, 2026-11-12: "maybe the user just
	 * wants to drink a non full potion").
	 */
	static boolean showsBox(boolean bankOpen, boolean whenBankClosed)
	{
		return bankOpen || whenBankClosed;
	}

	private static int titleHeight(FontMetrics metrics)
	{
		return metrics.getHeight() + 4;
	}

	private static Dimension gridSize(FontMetrics metrics, int rowCount, BoxLayout layout)
	{
		final BoxGrid grid = BoxGrid.of(rowCount, layout);
		final int width = Math.max(grid.columns() * COLUMN_WIDTH + 2 * PADDING,
			metrics.stringWidth(Texts.MISSING_TITLE) + TITLE_PADDING);
		return new Dimension(width, grid.rows() * ROW_HEIGHT + 2 * PADDING + titleHeight(metrics));
	}

	private static Dimension drawGrid(Graphics2D graphics, List<ShownResult.Row> rows, BoxLayout layout)
	{
		final FontMetrics metrics = graphics.getFontMetrics();
		final BoxGrid grid = BoxGrid.of(rows.size(), layout);
		final int perColumn = layout.rowsPerColumn();
		final Dimension size = gridSize(metrics, rows.size(), layout);
		final int top = titleHeight(metrics);
		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fillRect(0, 0, size.width, size.height);
		text(graphics, Texts.MISSING_TITLE, TITLE_COLOUR, (size.width - metrics.stringWidth(Texts.MISSING_TITLE)) / 2,
			2 + metrics.getAscent());
		for (int i = 0; i < grid.shown(); i++)
		{
			final ShownResult.Row row = rows.get(i);
			final Point cell = cellOrigin(i, perColumn, top);
			if (row.image != null)
			{
				graphics.drawImage(row.image, cell.x, cell.y + (ROW_HEIGHT - PICTURE_HEIGHT) / 2, PICTURE_WIDTH,
					PICTURE_HEIGHT, null);
			}
			text(graphics, "x" + row.count, Color.WHITE, cell.x + PICTURE_WIDTH + GAP, baseline(cell.y, metrics));
		}
		if (grid.more() > 0)
		{
			final Point cell = cellOrigin(grid.shown(), perColumn, top);
			text(graphics, "+" + grid.more(), Color.YELLOW, cell.x, baseline(cell.y, metrics));
		}
		return size;
	}

	private static Point cellOrigin(int index, int perColumn, int top)
	{
		final Point place = BoxGrid.place(index, perColumn);
		return new Point(PADDING + place.x * COLUMN_WIDTH, top + PADDING + place.y * ROW_HEIGHT);
	}

	private static int baseline(int rowTop, FontMetrics metrics)
	{
		return rowTop + (ROW_HEIGHT - (metrics.getAscent() + metrics.getDescent())) / 2 + metrics.getAscent();
	}

	/** Text with a 1 px black shadow, as the box and the message label draw it. */
	static void text(Graphics2D graphics, String text, Color colour, int x, int baseline)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, baseline + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, baseline);
	}
}

package com.inventoryquickcheck;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * Builds the outline ring around an item sprite: a band of one colour, a set number of pixels wide, hugging the
 * item's shape on the outside. Pure Java2D, nothing from the game.
 */
public final class Ring
{
	private Ring()
	{
	}

	/**
	 * The ring for {@code item}: an image {@code 2 * thickness} wider and taller, the item's own pixels at offset
	 * (thickness, thickness) left transparent, and every other pixel within {@code thickness} (square distance) of an
	 * opaque item pixel set to {@code colour}.
	 */
	public static BufferedImage of(BufferedImage item, int thickness, Color colour)
	{
		final int w = item.getWidth();
		final int h = item.getHeight();
		final BufferedImage out = new BufferedImage(w + 2 * thickness, h + 2 * thickness, BufferedImage.TYPE_INT_ARGB);
		final int argb = colour.getRGB() | 0xFF000000;
		for (int y = 0; y < h + 2 * thickness; y++)
		{
			for (int x = 0; x < w + 2 * thickness; x++)
			{
				if (opaque(item, x - thickness, y - thickness))
				{
					continue;
				}
				if (nearOpaque(item, x - thickness, y - thickness, thickness))
				{
					out.setRGB(x, y, argb);
				}
			}
		}
		return out;
	}

	/** Whether any pixel of the image is not fully transparent. */
	public static boolean hasPixels(BufferedImage image)
	{
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (opaque(image, x, y))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static boolean nearOpaque(BufferedImage item, int cx, int cy, int thickness)
	{
		for (int dy = -thickness; dy <= thickness; dy++)
		{
			for (int dx = -thickness; dx <= thickness; dx++)
			{
				if (opaque(item, cx + dx, cy + dy))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static boolean opaque(BufferedImage image, int x, int y)
	{
		if (x < 0 || y < 0 || x >= image.getWidth() || y >= image.getHeight())
		{
			return false;
		}
		return (image.getRGB(x, y) >>> 24) != 0;
	}
}

